<section class="hero"><h1>Ankesat e faturave</h1><p>Rrjedha: pranim, koordinator, komision, shqyrtim, vendim dhe përgjigje.</p></section>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Fatura / biznesi</th><th>Ankuesi</th><th>Ankesa</th><th>Statusi</th><th>Veprimi</th></tr></thead><tbody><?php foreach($appeals as $a):?><tr><td><?=e($a['invoice_number'])?><br><small><?=e($a['business_name_snapshot'])?></small></td><td><?=e($a['submitter_name'])?></td><td><strong><?=e($a['subject'])?></strong><br><?=nl2br(e($a['appeal_text']))?><?php if($a['decision_text']):?><hr><?=nl2br(e($a['decision_text']))?><?php endif;?></td><td><span class="badge"><?=e($a['status_code'])?></span></td><td><?php $next=['SUBMITTED'=>['ACCEPTED','REJECTED'],'ACCEPTED'=>['COORDINATOR'],'COORDINATOR'=>['COMMISSION'],'COMMISSION'=>['UNDER_REVIEW'],'UNDER_REVIEW'=>['DECIDED'],'DECIDED'=>['ANSWERED']][$a['status_code']]??[]; foreach($next as $status):?><form method="post" class="stack"><input type="hidden" name="_csrf" value="<?=e($csrf->token())?>"><input type="hidden" name="appeal_id" value="<?=(int)$a['id']?>"><input type="hidden" name="to_status" value="<?=e($status)?>"><?php if($status==='COMMISSION'):?><input name="commission_reference" placeholder="Referenca e komisionit" required><?php endif;?><?php if($status==='UNDER_REVIEW'):?><textarea name="review_notes" placeholder="Shënimet e shqyrtimit"></textarea><?php endif;?><?php if($status==='DECIDED'):?><select name="decision_code" required><option value="">Vendimi</option><option value="APPROVED">Aprovohet</option><option value="PARTIALLY_APPROVED">Aprovohet pjesërisht</option><option value="REJECTED">Refuzohet</option></select><textarea name="decision_text" placeholder="Arsyetimi" required></textarea><?php endif;?><input name="comment" placeholder="Koment"><button><?=e($status)?></button></form><?php endforeach;?></td></tr><?php endforeach;?></tbody></table><?php if($appeals===[]):?><div class="empty">Nuk ka ankesa.</div><?php endif;?></div></section>
